class StatusCli:
    ''' StatusCli
        show status
    '''
    def __init__(self, fw):
        self.fw = fw

    def show_status(self):
        commands = ['show status']
        output = self.fw.do_cli_commands(commands, 1)[1]
        return output

    def show_version(self):
        commands = ['diag show build-info']
        output = self.fw.do_cli_commands(commands, 1)[1]
        return output
        
    def show_rom_version(self):
        # for NSSP15700
        commands = ['show version']
        output = self.fw.do_cli_commands(commands, 1)[1]
        return output

    def show_diag_process(self, process=''):
        if process:
            commands = ['diag show process '+process]
        else:
            commands = ['diag show processes']
        output = self.fw.do_cli_commands(commands, 1)[1]
        return output


