    def config_admin(self, **kwargs):
        commands = ['configure', 'administration']
        self.fw._is_key_exist(commands, kwargs, 'name', key_new='admin name', tag=True)
        self.fw._is_key_exist(commands, kwargs, 'inactive-time', key_new='admin preempt-inactivity-timeout')
        self.fw._is_key_exist(commands, kwargs, 'unbind-totp-key', key_new='admin unbind-totp-key')
        # bool but only True
        self.fw._is_key_exist(commands, kwargs, 'preempt-action', key_new='admin preempt-action')
        if 'old_password' in kwargs.keys() and 'new_password' in kwargs.keys():
            commands.append('admin password old-password ' + kwargs['old_password'] + ' new-password ' +
                            kwargs['new_password'] + ' confirm-password ' + kwargs['new_password'])
        if 'one-time-pass' in kwargs.keys():
            check = kwargs['one-time-pass']
            if (isinstance(check, bool) and check) or \
               (isinstance(check, str) and check.lower() in ['yes', 'enable']) or \
               (isinstance(check, int) and check == 1):
                commands.append('admin one-time-password totp')
            else:
                commands.append('no admin one-time-password')
        commands.extend(['commit', 'end', 'end'])
        (rc, output) = self.fw.do_cli_commands(commands, 1)
        if not rc:
            logger.info(output)
        return rc

