        commands = ['configure', 'administration']
        self.fw._is_key_exist(commands, kwargs, 'mode', key_new='gms-management', tag=True)  # value bool
        if isinstance(kwargs['mode'], str):
            self.fw._is_key_exist(commands, kwargs, 'host-name', tag=True)
            self.fw._is_key_exist(commands, kwargs, 'heartbeat-status-only')  # bool
            self.fw._is_key_exist(commands, kwargs, 'syslog-server-port')
            if 'nat-device' in kwargs.keys():
                if isinstance(kwargs['nat-device'], str):
                    if re.search(r'\d+\.\d+\.\d+\.\d+', kwargs['nat-device'], re.S | re.M) is not None:
                        commands.append('behind-nat-device ip ' + kwargs['nat-device'])
