class SettingCli:
    ''' SettingCli

    '''
    def __init__(self, fw):
        self.fw = fw
        self.boot_time = 120

    def show_firmware(self):
        commands = ['show firmware']
        return self.fw.do_cli_commands(commands, 1)[1]
        
    def enable_safemode(self):
        commands = ['safemode']
        return self.fw.do_cli_commands(commands, 1)[1]

    def export_setting(self, **kwargs):
        if 'period' not in kwargs.keys() or 'mode' not in kwargs.keys() or \
           'protocol' not in kwargs.keys() or 'server' not in kwargs.keys():
            logger.error('Period, mode, protocol and server need to be specified.')
            return False
        mode = kwargs['mode']
        if kwargs['period'] == 'pending':
            mode = 'cli'
        self.fw.cli_login()
        command = 'export ' + kwargs['period'] + '-config ' + mode + ' ' + kwargs['protocol']
        output = ''
        if kwargs['protocol'].lower() == 'ftp':
            auth = ''
            if kwargs['user'] is not '' and kwargs['passwd'] is not '':
                auth = kwargs['user'] + ':' + kwargs['passwd'] + '@'
            command = command + ' ftp://' + auth + kwargs['server'] + '/setting'
            output = str(self.fw.do_cli_command(command))
        elif kwargs['protocol'].lower() == 'scp':
            command = command + ' scp://' + kwargs['user'] + '@' + kwargs['server'] + '/setting'
            output = str(self.fw.do_cli_command(command))
            if re.search(r'password:', output, re.M | re.I) is not None:
                output = output + str(self.fw.do_cli_command(kwargs['passwd']))

        if (re.search(r'Upload complete', output, re.M | re.I | re.S)) is not None:
            logger.info('Upload passed.')
            return True
        if re.search(r'No changes made', output, re.M | re.I) is not None:
            logger.info('No file for downloading.')
        logger.info(output)
        self.fw.ssh.sendline('exit')
        time.sleep(1)
        return False

    def import_setting(self, **kwargs):
        if 'protocol' not in kwargs.keys() or 'server' not in kwargs.keys() or 'file' not in kwargs.keys():
            logger.error('Please specify protocol, server, and file path')
            return False
        self.fw.cli_login()
        self.fw.do_cli_command('configure')
        command = 'import cli ' + kwargs['protocol']
        output = ''
        if kwargs['protocol'].lower() == 'ftp':
            auth = ''
            if kwargs['user'] is not '' and kwargs['passwd'] is not '':
                auth = kwargs['user'] + ':' + kwargs['passwd'] + '@'
            command = command + ' ftp://' + auth + kwargs['server'] + '/' + kwargs['file'] + ' merge'
            if 'best-effort' in kwargs.keys() and kwargs['best-effort']:
                command = command + ' best-effort'
            output = str(self.fw.do_cli_command(command, timeout=180))
        elif kwargs['protocol'].lower() == 'scp':
            command = command + ' scp://' + kwargs['user'] + '@' + kwargs['server'] + '/' + kwargs['file'] + \
                      ' merge'
            if 'best-effort' in kwargs.keys() and kwargs['best-effort']:
                command = command + ' best-effort'
            output = str(self.fw.do_cli_command(command))
            if re.search(r'password:', output, re.M | re.I) is not None:
                output = output + str(self.fw.do_cli_command(kwargs['passwd'], timeout=180))
        self.fw.do_cli_command('commit')
        self.fw.do_cli_command('end')
        logger.info('send command: exit')
        self.fw.ssh.sendline('exit')
        time.sleep(1)
        if (re.search(r'uploaded successfully', output, re.M | re.I | re.S)) is not None:
            logger.info('Import passed.')
            return True
        logger.info(output)
        return False

    def import_firmware(self, log_tag=False, **kwargs): # some test need CLI output, add para log_tag
        if 'protocol' not in kwargs.keys() or 'server' not in kwargs.keys() or 'file' not in kwargs.keys():
            logger.error('Please specify protocol, server, and file path')
            if log_tag:
                return False, 'Wrong parameters'
            return False
        self.fw.cli_login()
        self.fw.do_cli_command('configure')
        command = 'import firmware ' + kwargs['protocol']
        output = ''
        if kwargs['protocol'].lower() == 'ftp':
            auth = ''
            if kwargs['user'] is not '' and kwargs['passwd'] is not '':
                auth = kwargs['user'] + ':' + kwargs['passwd'] + '@'
            command = command + ' ftp://' + auth + kwargs['server'] + '/' + kwargs['file']
            output = str(self.fw.do_cli_command(command, timeout=180))
        elif kwargs['protocol'].lower() == 'scp':
            # import firmware scp user@server:/home/user/soniccore-sonicos-xxx.swi

            command = command + ' ' +kwargs['user'] + '@' + kwargs['server'] + ':' + kwargs['file']
            output = str(self.fw.do_cli_command(command))
            logger.info(output)
            if re.search(r'password:', output, re.M | re.I) is not None:
                output = output + str(self.fw.do_cli_command(kwargs['passwd'], timeout=300))
        self.fw.do_cli_command('commit')
        self.fw.do_cli_command('end')
        logger.info('send command: exit')
        self.fw.ssh.sendline('exit')
        time.sleep(1)
        
        if (re.search(r'uploaded successfully', output, re.M | re.I | re.S)) is not None:
            logger.info('Import passed.')
            if log_tag:
                return True, output
            return True
        elif re.search(r'The same Firmware already exists|image already present',output,re.M | re.I |re.S):
            logger.info('The same Firmware already exists')
            if log_tag:
                return False, output
            return output
        logger.info(output)
        if log_tag:
                return False, output
        return False

    def export_crrent_firmware(self, **kwargs):
        if 'file_path' not in kwargs.keys() or 'passwd' not in kwargs.keys() or 'server' not in kwargs.keys():
            logger.error('file_path and server and passwd need to be specified.')
            return False
        self.fw.cli_login()
        command = 'export firmware current scp root@' + kwargs['server'] + ':' + kwargs['file_path']
        output = str(self.fw.do_cli_command(command))
        if re.search(r'password:', output, re.M | re.I) is not None:
            resp = self.fw.do_cli_command(kwargs['passwd'])
            output = output + str(resp)

        if (re.search(r'Upload complete', output, re.M | re.I | re.S)) is not None:
            logger.info('Upload passed.')
            return True
        logger.info(output)
        self.fw.ssh.sendline('exit')
        time.sleep(1)
        return False

    def boot_firmware(self, build, mode='', consvr='', conport=''):
        commands = ['configure']
        commands.append('boot ' + build + ' ' + mode)
        commands.append('end')
        (rc, output) = self.fw.do_cli_commands(commands, 1)
        if not rc:
            logger.info(output)
        if is_Firewall_up(ip=self.fw.ip, console_ip=consvr, console_port=conport):
            logger.info('Firewall boots up')
            return rc
        logger.error('Firewall boots up failed.')
        return False

    def conf_firmware(self, **kwargs):
        commands = ['configure']
        if 'auto' in kwargs.keys() and 'auto_action' in kwargs.keys():
            commands.append(self.fw.simple_check_box('firmware auto ' + kwargs['auto_action'], kwargs['auto']))
        self.fw._is_key_exist(commands, kwargs, 'diagnostics', key_new='firmware diagnostics')  # bool
        commands.extend(['commit', 'end'])
        (rc, output) = self.fw.do_cli_commands(commands, 1)
        if not rc:
            logger.info(output)
        return rc

    def backup_firmware(self):
        self.fw.cli_login()
        self.fw.do_cli_command('configure')
        output = self.fw.do_cli_command('firmware backup', timeout=120)
        self.fw.do_cli_command('end')
        logger.info('send command:exit')
        self.fw.ssh.sendline('exit')
        time.sleep(1)
        if re.search(r'System Backup created successfully', str(output), re.M | re.I) is not None:
            return True
        logger.info(output)
        return False

    def restore(self, consvr, conport):
        commands = ['configure', 'restore-defaults']
        (rc, output) = self.fw.do_cli_commands(commands, 1)
        if not rc:
            logger.info(output)
        if is_Firewall_up(self.fw.ip, console_ip=consvr, console_port=conport):
            logger.info('Firewall boots up')
            return rc
        logger.error('Firewall boots up failed.')
        return False

    def restore_without_ssh_check(self, consvr, conport):
        commands = ['configure', 'restore-defaults']
        (rc, output) = self.fw.do_cli_commands_with_ip(commands, 1, change_ip=True, console_ip=consvr, console_port=conport)
        if not rc:
            logger.info(output)
            return False
        return rc

    def enable_ndpp(self):
        commands = ['configure', 'ndpp','commit','end']
        (rc, output) = self.fw.do_cli_commands(commands, 1)
        if not rc:
            logger.info(output)
        return rc   

    def enable_fips(self, msg=False, **kwargs):
        # support enable/disable fips via console.
        # kwargs = {'fips': False}
        commands = ['configure terminal']
        self.fw._is_key_exist(commands, kwargs, 'fips')   # bool

        for command in ['commit', 'end', 'exit']:
            commands.append(command)
        result = self.fw.do_cli_commands(commands, msg)
