class DiagnosticsCli:
    ''' DiagnosticsCli

    '''
    def __init__(self, fw):
        self.fw = fw

    def show_tsr(self, area=''):
        commands = ['show tech-support-report ' + area]
        return self.fw.do_cli_commands(commands, 1)[1]

    def get_tsr_part(self, func, lab1=None, lab2=None):
        tsr = self.show_tsr()
        start = "#" + func + " : " + lab1 + "_START"
        end   = "#" + func + " : " + lab1 + "_END"        
        pattern1 = start + '\n(.*)\n' + end
        lab1_match = re.search(r''+ pattern1 +'', tsr, re.I|re.S|re.M) 
        if lab1_match:
            tsr_part1 = lab1_match.group(1)
            if lab2:
                pattern2 = '--' + lab2 + '--\n(.*)(\n+)--'
                lab2_match = re.search(r''+ pattern2 +'', tsr_part1, re.I|re.S|re.M) 
                if lab2_match:
                    return lab2_match.group(1)
                else:
                    logger.error('Fail to get tsr.')
            else:
                return tsr_part1
        else:
            logger.error('Fail to get tsr.')
        return False

    def export_tsr(self, server, protocol, user='', passwd=''):
        self.fw.cli_login()
        output = ''
        if protocol.lower() == 'ftp':
            auth = ''
            if user is not '' and passwd is not '':
                auth = user + ':' + passwd + '@'
            command = 'export tech-support-report ftp ftp://' + auth + server + '/tsr.wri'
            output = str(self.fw.do_cli_command(command))
        elif protocol.lower() == 'scp':
            command = 'export tech-support-report scp scp://' + user + '@' + server + '/tsr.wri'
            output = str(self.fw.do_cli_command(command))
            if re.search(r'password:', output, re.M | re.I) is not None:
                output = output + str(self.fw.do_cli_command(passwd))
        if (re.search(r'Upload complete', output, re.M | re.I | re.S)) is not None:
            logger.info('Upload passed.')
            return True
        logger.info('send command: exit')
        self.fw.ssh.sendline('exit')
        time.sleep(1)
        logger.info(output)
        return False

    def ping(self, ip, iface='', ipv6=0):
        command = 'ping ' + ip
        if iface is not '':
            command = command + ' interface ' + iface
        if ipv6 != 0:
            command = command + ' ipv6-preferred'
        return self.fw.do_cli_commands([command], 1)[1]

    def traceroute(self, host, iface='', ipv6=0):
        command = 'traceroute ' + host
        if iface is not '':
            command = command + ' interface ' + iface
        if ipv6 != 0:
            command = command + ' ipv6-preferred'
        return self.fw.do_cli_commands([command], 1, 120)[1]

    def nslookup(self, domain, ipv6=0, dns=''):
        command = 'nslookup ' + domain
        if ipv6 != 0 :
            command = command + ' ipv6'
            if re.search(r'\d+\.\d+\.\d+\.\d+', dns, re.M | re.I | re.S) is not None:
                command = command + ' ipv4-dns ' + dns
            elif re.search(r':', dns) is not None:
                command = command + ' ipv6-dns ' + dns
        return self.fw.do_cli_commands([command], 1)[1]

    def rbl_lookup(self, ip, domain, dns):
        command = 'rbl-lookup ip ' + ip + ' domain ' + domain + ' dns-server ' + dns
        return self.fw.do_cli_commands([command], 1)[1]

    def network_path(self, ip):
        return self.fw.do_cli_commands(['network-path ' + ip], 1)[1]

    def reverse_lookup(self, ip, ipv6=0, dns=''):
        command = 'reverse-lookup ' + ip
        if ipv6 != 0:
            command = command + ' ipv6'
            if re.search(r'\d+\.\d+\.\d+\.\d+', dns, re.M | re.S) is not None:
                command = command + ' ipv4-dns ' + dns
            elif re.search(r':', dns) is not None:
                command = command + ' ipv6-dns ' + dns
        return self.fw.do_cli_commands([command], 1)[1]

    def geo_botnet_lookup(self, ip):
        return self.fw.do_cli_commands(['geo-botnet-lookup ' + ip], 1)[1]

    def mxlookup(self, domain, port=''):
        command = 'mxlookup ' + domain
        if port is not '':
            command = command + ' port ' + str(port)
        return self.fw.do_cli_commands([command], 1)[1]

    def pmtu_discovery(self, host, iface=''):
        command = 'pmtu-discovery ' + host
        if iface is not '':
            command = command + ' interface ' + str(iface)
        return self.fw.do_cli_commands([command], 1)[1]

    def conf_tsr(self, **kwargs):
        commands = ['configure', 'tech-support-report options']
        self.fw._is_key_exist(commands, kwargs, 'arp-cache')  # bool
        self.fw._is_key_exist(commands, kwargs, 'atp-cache')  # bool
        self.fw._is_key_exist(commands, kwargs, 'debug-info')  # bool
        self.fw._is_key_exist(commands, kwargs, 'dhcp-bindings')  # bool
        self.fw._is_key_exist(commands, kwargs, 'dns-proxy-cache')  # bool
        self.fw._is_key_exist(commands, kwargs, 'extra-routing')  # bool
        self.fw._is_key_exist(commands, kwargs, 'geo-ip-cache')  # bool
        self.fw._is_key_exist(commands, kwargs, 'ike-info')  # bool
        self.fw._is_key_exist(commands, kwargs, 'ip-stack-info')  # bool
        self.fw._is_key_exist(commands, kwargs, 'send-raw-flow-data')  # bool
        self.fw._is_key_exist(commands, kwargs, 'sonicpointn', key_new='sonicpointn diagnostics')  # bool
        self.fw._is_key_exist(commands, kwargs, 'vpn-keys', key_new='vpn-keys')  # bool
        if 'secure-backup' in kwargs.keys():
            if isinstance(kwargs['secure-backup'], bool):
                commands.append(self.fw.simple_check_box('secure-backup', kwargs['secure-backup']))
            else:
                commands.append(self.fw.simple_value('secure-backup interval', kwargs['secure-backup']))
        if 'ipv6' in kwargs.keys() and 'ipv6-pro' in kwargs.keys():
            commands.append(self.fw.simple_check_box('ipv6 ' + kwargs['ipv6-pro'], kwargs['ipv6']))
        if 'users' in kwargs.keys() and 'user-mode' in kwargs.keys():
            commands.append(self.fw.simple_check_box('users ' + kwargs['user-mode'], kwargs['users']))
        commands.extend(['commit', 'end', 'end'])
        (rc, output) = self.fw.do_cli_commands(commands, 1)
        if not rc:
            logger.info(output)
        return rc


class RestartCli:
    ''' RestartCli

    '''
    def __init__(self, fw):
        self.fw = fw

    def restart(self, time_info=''):
        commands = []
        if time_info is '':
            commands.append('restart')
        elif re.search(r'\d+:\d+:\d+:\d+:\d+:\d+', time_info, re.S) is not None:
            commands.append('restart at ' + time_info)
        elif re.search(r'\d+\s+\w+', time_info, re.S) is not None:
            commands.append('restart in ' + time_info)
        elif time_info.lower() == 'cancel':
            commands.append('restart cancel')
        (rc, output) = self.fw.do_cli_commands(commands, 1)
        if not rc:
            logger.info(output)
        return rc


