class NetworkAccessControlCli:
    """NetworkAccessControlCli"""

    def __init__(self, fw):
        self.fw = fw

    def enable_clearpass(self, enable=True):
        if enable:
            cmd = 'enable'
        else:
            cmd = 'no enable'
        commands = ['configure', 'network-access-control', 'clearpass', cmd, 'commit', 'end', 'end']
        (res, output) = self.fw.do_cli_commands(commands, 1)
        if not res:
            logger.info(output)
        return res

    def generate_json_web_token(self):
        commands = ['configure', 'network-access-control', 'clearpass',
                    'generate-json-web-token user-name admin',
                    'commit', 'end', 'end']
        (res, output) = self.fw.do_cli_commands(commands, 1)
        if not res:
            logger.info(output)
        return res

    def json_web_token_aging(self, day=15):
        commands = ['configure', 'network-access-control', 'clearpass',
                    f'json-web-token-aging {day}',
                    'commit', 'end', 'end']
        (res, output) = self.fw.do_cli_commands(commands, 1)
        if not res:
            logger.info(output)
        return res

    def config_clearpass_server(self, **kwargs):
        # kwargs = {
        #     'name': 'clearpass01.server.com',
        #     'edit_name': 'auto_test01',
        #     'password': 'password',
        #     'port': '8888',
        #     'user-name': 'user02',
        #     'client-id': '567890',
        # }
        commands = ['configure', 'network-access-control', 'clearpass']
        if 'name' in kwargs.keys():
            commands.append('server ' + kwargs['name'])
        if 'edit_name' in kwargs.keys():
            commands.append('name ' + kwargs['edit_name'])
        if 'password' in kwargs.keys():
            commands.append('password ' + kwargs['password'])
        if 'port' in kwargs.keys():
            commands.append('port ' + kwargs['port'])
        if 'user-name' in kwargs.keys():
            commands.append('user-name ' + kwargs['user-name'])
        if 'client-id' in kwargs.keys():
            commands.append('client-id ' + kwargs['client-id'])
        for cmd in ['commit', 'end', 'end']:
            commands.append(cmd)
        logger.info(commands)
        (res, output) = self.fw.do_cli_commands(commands, 1)
        if not res:
            logger.info(output)
        return res

    def get_clearpass_server(self, name='clearpass.server.com'):
        commands = [f'show network-access-control clearpass server {name}']
