class StorageCli:
    """StorageCli"""

    def __init__(self, fw):
        self.fw = fw

    def show_storage_files(self, file_type=''):
        # file_type:configuration-backup,configuration-backup-exp,diagnostics-data,logs ,packet-captures,system-logs,
        # threat-logs
        command = ['show storage-files']
        if file_type:
            command = ['show storage-files ' + file_type]
        output = self.fw.do_cli_commands(command, tag=1)[1]
        return output

    def list_storage_files_options(self):
        command = ['show storage-files ?']
        output = self.fw.do_cli_commands(command, tag=1)[1]
        return output

    def enable_logs_on_external_storage(self):
        commands = ['configure', 'storage', 'logs-on-external-storage ', 'commit', 'end', 'end']
        (rc, output) = self.fw.do_cli_commands(commands, 1)
        if not rc:
            logger.info(f'output is:{output}')
        return rc

    def disable_logs_on_external_storage(self):
        commands = ['configure', 'storage', 'no logs-on-external-storage ', 'commit', 'end', 'end']
        (rc, output) = self.fw.do_cli_commands(commands, 1)
        if not rc:
            logger.info(f'output is:{output}')
        return rc

    def show_storage(self):
        command = ['show storage']
        output = self.fw.do_cli_commands(command, tag=1)[1]
        return output

    def configure_log_external_storage_device(self, device):  # primary/secondary
        commands = ['configure', 'storage', f'log-external-storage-device {device}', 'commit', 'end', 'end']
        (rc, output) = self.fw.do_cli_commands(commands, 1)
        if not rc:
            logger.info(f'output is:{output}')
        return rc

    def edit_storage_usage_percent(self, storage_file, percent_value: str):
        # storage_file:configuration-backup,system-logs,diagnostic-data, packet-captures
        # percent_value:12
        commands = ['configure', 'storage', 'usage-percent ' + storage_file + ' ' + percent_value, 'commit', 'end',
                    'end']
        (rc, output) = self.fw.do_cli_commands(commands, 1)
        if not rc:
            logger.info(f'output is:{output}')
        return rc
